import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Первая загрузка","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-upload.md","filePath":"guide/first-upload.md","lastUpdated":1795455254000}`),a={name:`guide/first-upload.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="первая-загрузка" tabindex="-1">Первая загрузка <a class="header-anchor" href="#первая-загрузка" aria-label="Permalink to “Первая загрузка”">​</a></h1><p>Пошаговый путь от файла на диске до данных в Блокноте картографа. Занимает пару минут; для первого раза хватит небольшого GeoJSON.</p><h2 id="_1-откроите-редактор" tabindex="-1">1. Откройте редактор <a class="header-anchor" href="#_1-откроите-редактор" aria-label="Permalink to “1. Откройте редактор”">​</a></h2><p>Перейдите на <a href="https://n.maps.yandex.ru/" target="_blank" rel="noreferrer">n.maps.yandex.ru</a> и войдите в Яндекс ID. Если расширение только что установлено — обновите вкладку.</p><p>На панели редактора появится кнопка <strong>«Загрузить полигоны»</strong>. Она открывает окно загрузки.</p><h2 id="_2-выберите-фаил" tabindex="-1">2. Выберите файл <a class="header-anchor" href="#_2-выберите-фаил" aria-label="Permalink to “2. Выберите файл”">​</a></h2><p>Перетащите файл в окно или нажмите «Выбрать файл». Поддерживаются <code>.zip</code> (Shapefile), <code>.geojson</code>, <code>.gpx</code>, <code>.kml</code>, <code>.kmz</code>, <code>.topojson</code>, <code>.wkt</code> — полная таблица в разделе <a href="/yamapper/guide/formats">«Форматы»</a>.</p><p>После выбора файл конвертируется на вашем устройстве. Под ним появится статус: «сконвертирован» или ошибка с причиной.</p><p>Можно перетащить несколько файлов сразу: они обработаются по очереди, а в блокнот уйдут одним сохранением.</p><h2 id="_3-выберите-дату-блокнота" tabindex="-1">3. Выберите дату блокнота <a class="header-anchor" href="#_3-выберите-дату-блокнота" aria-label="Permalink to “3. Выберите дату блокнота”">​</a></h2><p>Поле «Дата блокнота» задаёт, в какую запись попадут данные. По умолчанию — сегодня. Даты, на которые в блокноте уже есть запись, помечены в календаре: это не ошибка, загрузка дополнит существующую запись, не затирая её.</p><p>Подробнее — <a href="/yamapper/guide/editor/#notebook-date">«Дата блокнота»</a>.</p><h2 id="_4-нажмите-«загрузить»" tabindex="-1">4. Нажмите «Загрузить» <a class="header-anchor" href="#_4-нажмите-«загрузить»" aria-label="Permalink to “4. Нажмите «Загрузить»”">​</a></h2><p>Расширение:</p><ol><li>проверит доступ к Яндекс Диску (при первом запуске попросит разрешение и вход);</li><li>прочитает текущий <code>index.json</code> за выбранную дату;</li><li>допишет новые объекты и сохранит файл обратно;</li><li>покажет «Загрузка завершена».</li></ol><p>Данные лежат в <code>Приложения/Блокнот картографа Народной карты</code>, внутри — папки с датами <code>гггг-мм-дд</code>.</p><h2 id="_5-проверьте-результат" tabindex="-1">5. Проверьте результат <a class="header-anchor" href="#_5-проверьте-результат" aria-label="Permalink to “5. Проверьте результат”">​</a></h2><p>Вернитесь в редактор и выберите в блокноте ту же дату, что указали при загрузке. Объекты должны появиться на карте.</p><p>Если их нет:</p><ul><li>сверьте дату в блокноте и в поле загрузки;</li><li>включите <a href="/yamapper/guide/editor/#reload-after-upload">автообновление после загрузки</a> или обновите страницу карты;</li><li>проверьте, что редактор и расширение авторизованы под одним аккаунтом.</li></ul><p>Разбор остальных случаев — в разделе <a href="/yamapper/guide/faq#uploaded-not-visible">«Вопросы и типичные ошибки»</a>.</p><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to “Что дальше”">​</a></h2><ul><li><a href="/yamapper/guide/editor/#tracing">Трассировка</a> — обвести смежный объект по загруженной границе.</li><li><a href="/yamapper/guide/editor/#point-counter">Счётчик вершин</a> — держать контур в пределах лимита.</li><li><a href="/yamapper/guide/style/#stroke-color">Обводка контура</a> — выделить свои данные цветом.</li></ul>`,23)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};